-- Production table SHAPES (columns, defaults, checks, uniques, the FKs among these tables)
-- captured read-only from the live catalog on 2026-09-11. No production rows.
SET client_min_messages = warning;
DO $r$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='anon') THEN CREATE ROLE anon NOLOGIN; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='authenticated') THEN CREATE ROLE authenticated NOLOGIN; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='service_role') THEN CREATE ROLE service_role NOLOGIN; END IF;
END $r$;
CREATE TABLE public.tournaments (id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY, name text NOT NULL, status text DEFAULT 'ANNOUNCED'::text NOT NULL, ended_at timestamp with time zone, is_bounty boolean DEFAULT false, is_pko boolean DEFAULT false, is_mystery_bounty boolean DEFAULT false, bounty_amount numeric(15,2) DEFAULT 0, bounty_pool numeric(18,2) DEFAULT 0 NOT NULL, bounty_pool_paid numeric DEFAULT 0 NOT NULL, prize_pool numeric(18,2) DEFAULT 0, prize_pool_finalized boolean DEFAULT false, mystery_bounty_stage text DEFAULT 'pending'::text NOT NULL, mystery_bounty_activated_at timestamp with time zone, mystery_bounty_activated_players integer, mystery_bounty_pool_cents bigint, mystery_bounty_activation_generation bigint DEFAULT 0 NOT NULL, mystery_bounty_pool_percent numeric DEFAULT 50 NOT NULL, mystery_bounty_regular_pool_percent numeric DEFAULT 50 NOT NULL);
CREATE TABLE public.financial_alerts (id uuid DEFAULT gen_random_uuid() NOT NULL, severity text NOT NULL, source text NOT NULL, message text NOT NULL, context jsonb DEFAULT '{}'::jsonb, resolved boolean DEFAULT false NOT NULL, resolved_at timestamp with time zone, created_at timestamp with time zone DEFAULT now() NOT NULL, resolved_by uuid, resolution text);
CREATE TABLE public.tournament_bounties (id uuid DEFAULT gen_random_uuid() NOT NULL, tournament_id uuid NOT NULL, eliminated_player_id uuid NOT NULL, collector_player_id uuid NOT NULL, bounty_amount numeric(20,2) NOT NULL, added_to_collector_bounty numeric(20,2) DEFAULT 0, is_mystery_revealed boolean DEFAULT false, created_at timestamp with time zone DEFAULT now() NOT NULL, bounty_obligation_id uuid);
CREATE TABLE public.tournament_bounty_award_recipients (id uuid DEFAULT gen_random_uuid() NOT NULL, award_id uuid NOT NULL, user_id uuid NOT NULL, amount_cents bigint NOT NULL, is_designated_revealer boolean DEFAULT false NOT NULL, paid_at timestamp with time zone, terminal_closed_at timestamp with time zone);
CREATE TABLE public.tournament_bounty_awards (id uuid DEFAULT gen_random_uuid() NOT NULL, tournament_id uuid NOT NULL, chest_id uuid NOT NULL, table_id uuid, hand_id text, eliminated_user_id uuid NOT NULL, amount_cents bigint NOT NULL, tier text NOT NULL, status text DEFAULT 'reserved'::text NOT NULL, op_id uuid NOT NULL, reserved_at timestamp with time zone DEFAULT now() NOT NULL, revealed_at timestamp with time zone, paid_at timestamp with time zone, reveal_deadline_at timestamp with time zone, bounty_obligation_id uuid, activation_generation bigint, terminal_closed_at timestamp with time zone);
CREATE TABLE public.tournament_bounty_chests (id uuid DEFAULT gen_random_uuid() NOT NULL, tournament_id uuid NOT NULL, seq integer NOT NULL, tier text NOT NULL, amount_cents bigint NOT NULL, status text DEFAULT 'available'::text NOT NULL, award_id uuid, created_at timestamp with time zone DEFAULT now() NOT NULL, terminal_closed_at timestamp with time zone);
CREATE TABLE public.tournament_bounty_completion_receipts (tournament_id uuid NOT NULL, winner_user_id uuid, mystery_settled_at timestamp with time zone, mystery_result jsonb, pool_finalized_at timestamp with time zone, pool_result jsonb, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.tournament_bounty_obligations (id uuid DEFAULT gen_random_uuid() NOT NULL, tournament_id uuid NOT NULL, eliminated_user_id uuid NOT NULL, table_id uuid NOT NULL, hand_id uuid NOT NULL, hand_number bigint NOT NULL, settlement_completed_at timestamp with time zone NOT NULL, seat_joined_at timestamp with time zone NOT NULL, "position" integer NOT NULL, prize numeric(20,2) NOT NULL, bubble_refund numeric(20,2) DEFAULT 0 NOT NULL, mode text NOT NULL, activation_generation bigint DEFAULT 0 NOT NULL, head_amount numeric(20,2) NOT NULL, knocker_user_id uuid NOT NULL, claimants jsonb NOT NULL, state text DEFAULT 'pending'::text NOT NULL, attempt_count integer DEFAULT 0 NOT NULL, next_attempt_at timestamp with time zone DEFAULT now() NOT NULL, last_error text, created_at timestamp with time zone DEFAULT now() NOT NULL, settled_at timestamp with time zone);
CREATE TABLE public.tournament_escrow (tournament_id uuid NOT NULL, enforced boolean DEFAULT true NOT NULL, gross_in numeric DEFAULT 0 NOT NULL, fee_entries_in numeric DEFAULT 0 NOT NULL, satellite_fee_in numeric DEFAULT 0 NOT NULL, bounty_in numeric DEFAULT 0 NOT NULL, overlay_in numeric DEFAULT 0 NOT NULL, satellite_in numeric DEFAULT 0 NOT NULL, prize_out numeric DEFAULT 0 NOT NULL, bounty_out numeric DEFAULT 0 NOT NULL, fee_out numeric DEFAULT 0 NOT NULL, refund_prize numeric DEFAULT 0 NOT NULL, refund_bounty numeric DEFAULT 0 NOT NULL, refund_fee numeric DEFAULT 0 NOT NULL, prize_balance numeric(15,2) DEFAULT 0 NOT NULL, bounty_balance numeric(15,2) DEFAULT 0 NOT NULL, fee_balance numeric(15,2) DEFAULT 0 NOT NULL, opened_at timestamp with time zone DEFAULT now() NOT NULL, opened_from text NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, closed_at timestamp with time zone, close_note text, reserve_out numeric DEFAULT 0 NOT NULL, reserve_in numeric DEFAULT 0 NOT NULL, terminal_closed_at timestamp with time zone);
CREATE TABLE public.tournament_knockout_candidates (id uuid DEFAULT gen_random_uuid() NOT NULL, tournament_id uuid NOT NULL, eliminated_user_id uuid NOT NULL, table_id uuid NOT NULL, seat_id uuid NOT NULL, seat_joined_at timestamp with time zone NOT NULL, hand_id uuid NOT NULL, hand_number bigint NOT NULL, stack_before numeric(20,2) NOT NULL, stack_after numeric(20,2) NOT NULL, state text DEFAULT 'pending'::text NOT NULL, rebuy_prompt_until timestamp with time zone, created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL, resolved_at timestamp with time zone);
