CREATE TABLE public.tournament_players (id uuid DEFAULT gen_random_uuid() NOT NULL, tournament_id uuid NOT NULL, user_id uuid NOT NULL, username text, chips integer DEFAULT 0, status text DEFAULT 'registered'::text, "position" integer, prize numeric(15,2) DEFAULT 0, rebuys integer DEFAULT 0, add_on boolean DEFAULT false, registered_at timestamp with time zone DEFAULT now(), eliminated_at timestamp with time zone, bounties_collected integer DEFAULT 0, bounty_winnings numeric(15,2) DEFAULT 0, mystery_bounty_value numeric(15,2) DEFAULT 0, current_bounty numeric DEFAULT 0, table_id uuid, seat_number integer, chip_count numeric DEFAULT 0, club_id uuid, is_satellite_qualifier boolean DEFAULT false, rebuy_prompt_until timestamp with time zone, push_15m_sent boolean DEFAULT false, push_2m_sent boolean DEFAULT false, source_satellite_id uuid, elimination_sequence bigint, terminal_closed_at timestamp with time zone);
